namespace Astera {
static class FtlDiscovery {
    internal static List<string> Find(){var roots=new HashSet<string>(StringComparer.OrdinalIgnoreCase);var result=new List<string>();string steam=Convert.ToString(Microsoft.Win32.Registry.GetValue(@"HKEY_CURRENT_USER\Software\Valve\Steam","SteamPath",null));if(!String.IsNullOrEmpty(steam))roots.Add(steam);roots.Add(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFilesX86),"Steam"));foreach(var root in roots.ToArray())try{string libraries=Path.Combine(root,"steamapps","libraryfolders.vdf");if(File.Exists(libraries))foreach(Match match in Regex.Matches(File.ReadAllText(libraries),"\"path\"\\s+\"([^\"]+)\""))roots.Add(match.Groups[1].Value.Replace("\\\\","\\"));}catch(IOException){}catch(UnauthorizedAccessException){}
        foreach(var root in roots)try{string manifest=Path.Combine(root,"steamapps","appmanifest_212680.acf");if(!File.Exists(manifest))continue;var match=Regex.Match(File.ReadAllText(manifest),"\"installdir\"\\s+\"([^\"]+)\"");if(!match.Success||Path.GetFileName(match.Groups[1].Value)!=match.Groups[1].Value)continue;string game=Path.Combine(root,"steamapps","common",match.Groups[1].Value);if(File.Exists(Path.Combine(game,"FTLGame.exe"))&&File.Exists(Path.Combine(game,"ftl.dat")))result.Add(game);}catch(IOException){}catch(UnauthorizedAccessException){}return result.Distinct(StringComparer.OrdinalIgnoreCase).ToList();
    }
    internal static bool Steam(string folder){try{var root=Directory.GetParent(Directory.GetParent(Engine.Root(folder)).FullName).FullName;string manifest=Path.Combine(root,"appmanifest_212680.acf");if(!File.Exists(manifest))return false;var match=Regex.Match(File.ReadAllText(manifest),"\"installdir\"\\s+\"([^\"]+)\"");return match.Success&&Path.GetFileName(folder).Equals(match.Groups[1].Value,StringComparison.OrdinalIgnoreCase);}catch{return false;}}
}
sealed class MultiverseSettings:AsteraDialog {
    internal string Game,Workspace;internal bool GeneratedGibs,RenegadeCollection;readonly TextBox folder=new TextBox(),work=new TextBox();
    internal MultiverseSettings(string game,string workspace,bool generatedGibs=true,bool renegadeCollection=true){Text="FTL: Multiverse • Setup";Size=new Size(830,460);MinimumSize=Size;StartPosition=FormStartPosition.CenterParent;BackColor=Color.FromArgb(21,28,47);ForeColor=Color.White;Font=UiTheme.Text(14);
        var grid=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(22),ColumnCount=2,RowCount=8};grid.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));grid.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,130));Controls.Add(grid);
        grid.Controls.Add(new Label{Text="Existing FTL installation (Steam, Epic or another supported Windows copy)",AutoSize=true},0,0);grid.SetColumnSpan(grid.GetControlFromPosition(0,0),2);folder.Text=game;folder.Dock=DockStyle.Fill;grid.Controls.Add(folder,0,1);var choose=new AsteraButton{Text="Choose…"};LibraryForm.Style(choose);choose.Click+=delegate{using(var d=new ExplorerFolderDialog{Description="Select the folder containing FTLGame.exe and ftl.dat",SelectedPath=folder.Text})if(d.ShowDialog()==DialogResult.OK)folder.Text=d.SelectedPath;};grid.Controls.Add(choose,1,1);
        grid.Controls.Add(new Label{Text="Downloads, staging and backups (allow several GB of free space)",AutoSize=true},0,2);work.Text=workspace;work.Dock=DockStyle.Fill;grid.Controls.Add(work,0,3);var chooseWork=new AsteraButton{Text="Choose…"};LibraryForm.Style(chooseWork);chooseWork.Click+=delegate{using(var d=new ExplorerFolderDialog{Description="Choose a workspace outside the FTL game folder",SelectedPath=work.Text})if(d.ShowDialog()==DialogResult.OK)work.Text=d.SelectedPath;};grid.Controls.Add(chooseWork,1,3);
        var gibs=new CheckBox{Text="Ship breakup effects (Generated Gibs) — optional, adds about 67 MiB and increases loading/memory use",AutoSize=true,Checked=generatedGibs,MaximumSize=new Size(730,0)};grid.Controls.Add(gibs,0,4);grid.SetColumnSpan(gibs,2);
        var trc=new CheckBox{Text="The Renegade Collection — extra ships, weapons and encounters",AutoSize=true,Checked=renegadeCollection};grid.Controls.Add(trc,0,5);grid.SetColumnSpan(trc,2);var help=new Label{Text="Start with a vanilla copy. Existing unmanaged mods must be reverted using their current manager first. Astera stages changes, backs up replaced files and leaves saves alone.",AutoSize=true,MaximumSize=new Size(730,0),Margin=new Padding(0,12,0,8)};grid.Controls.Add(help,0,6);grid.SetColumnSpan(help,2);
        var save=new AsteraButton{Text="Link FTL"};LibraryForm.Style(save);save.Click+=delegate{try{Multiverse.ValidateRoot(folder.Text.Trim());GeneratedGibs=gibs.Checked;RenegadeCollection=trc.Checked;Game=Engine.Root(folder.Text.Trim());Workspace=Engine.Root(work.Text.Trim());if(Workspace.Equals(Game,StringComparison.OrdinalIgnoreCase)||Workspace.StartsWith(Game+"\\",StringComparison.OrdinalIgnoreCase)||Game.StartsWith(Workspace+"\\",StringComparison.OrdinalIgnoreCase))throw new Exception("Keep the workspace outside the FTL installation.");DialogResult=DialogResult.OK;Close();}catch(Exception error){MessageBox.Show(this,error.Message,"FTL setup");}};grid.Controls.Add(save,1,7);
    }
}
sealed partial class LibraryForm {
    FtlPlan multiversePlan;bool multiversePrepared,multiverseUpdate;string multiverseNotice="Check the official Multiverse releases to begin.";
    bool IsMultiverse {get{return GameKind==2;}}
    string FtlWorkspace {get{return String.IsNullOrWhiteSpace(store.Settings.FtlWorkspace)?Multiverse.DefaultWorkspace(store):store.Settings.FtlWorkspace;}}
    FtlState FtlInstalled(){try{return Multiverse.State(store.Settings.FtlDirectory);}catch(Exception error){multiverseNotice=error.Message;return null;}}
    void ConfigureMultiverse(){if(busy)return;string root=store.Settings.FtlDirectory;if(String.IsNullOrWhiteSpace(root)){var found=FtlDiscovery.Find();if(found.Count==1)root=found[0];}using(var setup=new MultiverseSettings(root,FtlWorkspace,store.Settings.FtlGeneratedGibs,store.Settings.FtlRenegadeCollection)){if(setup.ShowDialog(this)!=DialogResult.OK)return;store.Settings.FtlDirectory=setup.Game;store.Settings.FtlWorkspace=setup.Workspace;store.Settings.FtlGeneratedGibs=setup.GeneratedGibs;store.Settings.FtlRenegadeCollection=setup.RenegadeCollection;multiverseUpdate=false;store.Save();multiversePlan=null;multiversePrepared=false;RefreshView();}}
    void RefreshMultiverseView(){var state=FtlInstalled();bool linked=!String.IsNullOrWhiteSpace(store.Settings.FtlDirectory);banner.Game="FTL: Multiverse";((AsteraButton)play).Symbol=state!=null&&!multiverseUpdate?ButtonSymbol.Play:ButtonSymbol.Install;play.Text=state!=null?(multiverseUpdate?"UPDATE":"PLAY"):linked?"INSTALL":"SET UP";play.Enabled=!busy;check.Enabled=!busy;download.Enabled=!busy&&multiversePlan!=null&&!multiversePrepared;install.Enabled=!busy&&multiversePrepared;restore.Enabled=!busy&&(state!=null||Multiverse.Pending(store.Settings.FtlDirectory,FtlWorkspace)!=null);cancel.Enabled=busy&&cancellation!=null&&!transaction;settings.Enabled=games.Enabled=!busy;
        status.ForeColor=multiverseUpdate?Color.LightGreen:Color.White;status.Text=state==null?"Multiverse is not managed here yet":multiverseUpdate?"Update ready • "+multiversePlan.DataVersion:"Installed • Multiverse "+state.DataVersion;
        profileLabel.Text=linked?store.Settings.FtlDirectory:"Link your existing FTL installation in Setup.";notes.Text=PatchNotes.PlayerText(multiversePlan!=null&&!String.IsNullOrWhiteSpace(multiversePlan.OfficialNotes)?"FTL: Multiverse — Official Release Notes\n\n"+multiversePlan.OfficialNotes:PatchNotes.FtlPlaceholder);releaseLabel.Text=multiversePrepared?"Ready to install":multiverseUpdate?"An update is available.":state!=null?"Ready to play":"Choose your installation to get started.";games.Invalidate();UpdateLayoutView();
    }
    async Task CheckMultiverse(bool background){if(String.IsNullOrWhiteSpace(store.Settings.FtlDirectory)){if(!background)ConfigureMultiverse();if(String.IsNullOrWhiteSpace(store.Settings.FtlDirectory))return;}multiversePlan=null;multiversePrepared=false;multiverseUpdate=false;await Work(delegate{ReportWorkProgress("Checking official Multiverse releases",0,0);var selected=Multiverse.Check(store.Settings.FtlDirectory,FtlWorkspace,cancellation.Token);Multiverse.SelectGibs(selected,store.Settings.FtlGeneratedGibs);Multiverse.SelectTrc(selected,store.Settings.FtlRenegadeCollection);multiversePlan=selected;multiversePrepared=false;var installed=multiversePlan.Previous;multiverseUpdate=Multiverse.NeedsUpdate(installed,multiversePlan);multiverseNotice="Available: Multiverse Data "+multiversePlan.DataVersion+", Assets "+multiversePlan.AssetsVersion+", Hyperspace "+multiversePlan.HyperspaceVersion+(multiversePlan.Gibs==null?"":"; ship breakup effects: Generated Gibs "+multiversePlan.GibsVersion)+(multiversePlan.Trc==null?"":"; The Renegade Collection "+multiversePlan.TrcVersion)+".\nDownload size: "+((Multiverse.Payloads(multiversePlan).Sum(a=>a.Size))/1048576D).ToString("0.0")+" MiB before cached files are reused.";Log(multiverseNotice);},background,"builtin:2");}
    async Task DownloadMultiverse(){if(multiversePlan==null)return;var selected=multiversePlan;await Work(delegate{Multiverse.Fetch(selected,cancellation.Token,Log,ReportWorkProgress);Multiverse.Prepare(selected,cancellation.Token,Log,ReportWorkProgress);multiversePrepared=true;multiverseNotice="Prepared and verified: "+selected.Candidate.Count+" files. Your FTL folder has not changed. Choose Install update when ready.";},false,"builtin:2");}
    async Task InstallMultiverse(){if(!multiversePrepared||multiversePlan==null)return;var selected=multiversePlan;string summary="Install Multiverse Data "+selected.DataVersion+" / Assets "+selected.AssetsVersion+" and Hyperspace "+selected.HyperspaceVersion+(selected.Gibs==null?"":" with Generated Gibs "+selected.GibsVersion+" ship breakup effects")+(selected.Trc==null?"":" with The Renegade Collection "+selected.TrcVersion)+"?\n\nFolder: "+selected.Root+"\n\n"+selected.Candidate.Count+" game files will be replaced or added. Existing versions are backed up to:\n"+selected.Workspace+"\n\nSaves and unrelated files are preserved. Close FTL first.";if(MessageBox.Show(this,summary,"Install FTL: Multiverse",MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)return;transaction=true;try{await Work(delegate{ReportWorkProgress("Backing up and installing Multiverse",0,0);Multiverse.Apply(selected,Log);multiversePrepared=false;multiverseUpdate=false;multiverseNotice="Multiverse "+selected.DataVersion+" is installed. Your backup is available through Restore backup.";},false,"builtin:2");}finally{transaction=false;RefreshView();}}
    async Task RestoreMultiverse(){if(MessageBox.Show(this,"Restore the previous FTL game files?\n\nChanged managed files cause restore to stop rather than overwrite them. Saves and unrelated files stay intact.","Restore FTL",MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)return;transaction=true;try{await Work(delegate{if(Multiverse.Pending(store.Settings.FtlDirectory,FtlWorkspace)!=null)Multiverse.Recover(store.Settings.FtlDirectory,FtlWorkspace,Log);else Multiverse.Restore(store.Settings.FtlDirectory,FtlWorkspace,Log);multiversePlan=null;multiversePrepared=false;multiverseUpdate=false;multiverseNotice="Previous installation restored.";},false,"builtin:2");}finally{transaction=false;RefreshView();}}
    async void PrimaryMultiverse(){if(String.IsNullOrWhiteSpace(store.Settings.FtlDirectory)){ConfigureMultiverse();return;}if(FtlInstalled()==null||multiverseUpdate){await CheckMultiverse(false);if(multiversePlan==null)return;await DownloadMultiverse();if(multiversePrepared)await InstallMultiverse();return;}try{bool verified=false;await Work(delegate{Multiverse.ValidateRoot(store.Settings.FtlDirectory);var installed=Multiverse.State(store.Settings.FtlDirectory);foreach(var pair in installed.Files)if(Engine.Hash(Engine.Inside(store.Settings.FtlDirectory,pair.Key))!=pair.Value)throw new Exception("A managed FTL file changed. Check/restore the installation before launching.");verified=true;},false,"builtin:2");if(!verified)return;string target=FtlDiscovery.Steam(store.Settings.FtlDirectory)?"steam://rungameid/212680":Path.Combine(store.Settings.FtlDirectory,"FTLGame.exe");Process.Start(new ProcessStartInfo(target){UseShellExecute=true,WorkingDirectory=store.Settings.FtlDirectory});TrackLaunchedGame("builtin:2",new CustomGame{Executable=store.Settings.FtlDirectory,Platform="folder",PlatformId=FtlDiscovery.Steam(store.Settings.FtlDirectory)?"212680":""});}catch(Exception error){AsteraDiagnostics.Write("FTL launch failed",error);CaptureFtlReports();MessageBox.Show(this,error.Message,"Play FTL: Multiverse");}}
}
}
